  if (!obj || !path) return defaultValue as T;
  const keys = path
    .replace(/\[(\d+)\]/g, '.$1')
    .split('.')
    .filter(Boolean);
  let result: any = obj;
  for (const key of keys) {
    if (result == null) return defaultValue as T;
    result = result[key];
  }
  return result === undefined ? (defaultValue as T) : result;
}

